(4117633, 590650, 78132, '<td valign="top">Love the bright colors!</td>', 'Love the bright colors!', '2007-09-26 14:17:03.000000', NULL, 1),
(4117636, 591615, 84440, '<td valign="top">I see the S shape. But there is nothing appealing about this photo, or even unappealing to make it interesting. There is little sense of depth, in part due to the poor lighting. Colors are washed out.</td>', 'I see the S shape. But there is nothing appealing about this photo, or even unappealing to make it interesting. There is little sense of depth, in part due to the poor lighting. Colors are washed out.', '2007-09-26 14:18:00.000000', NULL, 1),
