(4122805, 591205, 66267, '<td valign="top">Crazy if it were only a lil better (crazy good that is)</td>', 'Crazy if it were only a lil better (crazy good that is)', '2007-09-28 17:14:13.000000', NULL, 1),
(4122806, 591347, 66267, '<td valign="top">Very graphic design</td>', 'Very graphic design', '2007-09-28 17:14:43.000000', NULL, 1),
