(4123042, 591259, 74242, '<td valign="top">Ofcourse, it is very much ''Natural'' :D (7)</td>', 'Ofcourse, it is very much ''Natural'' :D (7)', '2007-09-28 18:57:35.000000', NULL, 1),
(4123046, 591786, 74242, '<td valign="top">This one''s definitely my first choice .It''s gloriuos ..V gud work ! (9) :)</td>', 'This one''s definitely my first choice .It''s gloriuos ..V gud work ! (9) :)', '2007-09-28 19:00:02.000000', NULL, 1),
(4123070, 591516, 82817, '<td valign="top">Sssssssssssss''s. Definitely meets the challenge. A bit more saturation could be useful.</td>', 'Sssssssssssss''s. Definitely meets the challenge. A bit more saturation could be useful.', '2007-09-28 19:19:00.000000', NULL, 1),
(4123072, 591205, 82817, '<td valign="top">I am being led out of the photo by the S. Lovely sunset.</td>', 'I am being led out of the photo by the S. Lovely sunset.', '2007-09-28 19:20:04.000000', NULL, 1),
(4123075, 591738, 82817, '<td valign="top">Seems like a reverse of the S and my eye wanders up and down the photo looking for something to really look at. More vibrant colors would help.</td>', 'Seems like a reverse of the S and my eye wanders up and down the photo looking for something to really look at. More vibrant colors would help.', '2007-09-28 19:21:53.000000', NULL, 1),
(4123077, 590112, 82817, '<td valign="top">My eye keeps looking at the white circular mark on the shoulder. I get led into the photo then see the circle and wonder about it.</td>', 'My eye keeps looking at the white circular mark on the shoulder. I get led into the photo then see the circle and wonder about it.', '2007-09-28 19:23:19.000000', NULL, 1),
(4123079, 590265, 82817, '<td valign="top">I am drawn more to the upper part of the photo and then follow the snake down to see the in focus head.</td>', 'I am drawn more to the upper part of the photo and then follow the snake down to see the in focus head.', '2007-09-28 19:25:53.000000', NULL, 1),
(4123081, 590224, 82817, '<td valign="top">Love the sky and even though the S in the river is not too distinct I am really drawn into the photo. Meets the challenge and then some. Love the desat.</td>', 'Love the sky and even though the S in the river is not too distinct I am really drawn into the photo. Meets the challenge and then some. Love the desat.', '2007-09-28 19:27:13.000000', NULL, 1),
(4123086, 589511, 82817, '<td valign="top">The red is incredibly intense and a bit distracting to me. It does however cause the eye to go vertical and meets the challenge.</td>', 'The red is incredibly intense and a bit distracting to me. It does however cause the eye to go vertical and meets the challenge.', '2007-09-28 19:29:28.000000', NULL, 1),
(4123090, 589947, 82817, '<td valign="top">Photo is pretty washed out and the blackish spot in the lower left is calling for my attention. A tighter crop and more vibrant colors would really make a difference.</td>', 'Photo is pretty washed out and the blackish spot in the lower left is calling for my attention. A tighter crop and more vibrant colors would really make a difference.', '2007-09-28 19:31:31.000000', NULL, 1),
(4123092, 590352, 82817, '<td valign="top">Nice use of DOF and the bright red sweater.</td>', 'Nice use of DOF and the bright red sweater.', '2007-09-28 19:32:14.000000', NULL, 1),
(4123093, 589381, 82817, '<td valign="top">Beautiful location. The light is a bit bright in the trees and the sky a bit washed out. Would love to shoot there. Photos that is.</td>', 'Beautiful location. The light is a bit bright in the trees and the sky a bit washed out. Would love to shoot there. Photos that is.', '2007-09-28 19:33:40.000000', NULL, 1),
(4123097, 591818, 82817, '<td valign="top">The guardrail or whatever it is keeps me out of the shot. The most interesting part to me is the guardrail and the grass just beyond it. Like the S but nothing holds my interest out there.</td>', 'The guardrail or whatever it is keeps me out of the shot. The most interesting part to me is the guardrail and the grass just beyond it. Like the S but nothing holds my interest out there.', '2007-09-28 19:35:44.000000', NULL, 1),
(4123098, 591511, 74741, '<td valign="top">Love the shot, but where is the S</td>', 'Love the shot, but where is the S', '2007-09-28 19:36:00.000000', NULL, 1),
(4123100, 589381, 43774, '<td valign="top">One of my favourites, the water is gorgeous, as is the scenery and light.</td>', 'One of my favourites, the water is gorgeous, as is the scenery and light.', '2007-09-28 19:37:02.000000', NULL, 1),
(4123101, 590257, 82817, '<td valign="top">Vertical S works for me. The stairs and the blue. A little dark below but this is tough to compensate for in basic editing.</td>', 'Vertical S works for me. The stairs and the blue. A little dark below but this is tough to compensate for in basic editing.', '2007-09-28 19:37:09.000000', NULL, 1),
(4123102, 590460, 43774, '<td valign="top">Very nice, I like that there is still light in the sky.</td>', 'Very nice, I like that there is still light in the sky.', '2007-09-28 19:37:20.000000', NULL, 1),
