(4123105, 591560, 60505, '<td valign="top">Great photo but I cany score it up as not v Curvy except the tongue!</td>', 'Great photo but I cany score it up as not v Curvy except the tongue!', '2007-09-28 19:37:58.000000', NULL, 1),
(4123106, 590936, 43774, '<td valign="top">Very nice, clear, good job</td>', 'Very nice, clear, good job', '2007-09-28 19:38:11.000000', NULL, 1),
(4123107, 591511, 82817, '<td valign="top">I am confused about the S in this photo. Where is it? Nice balloon, landscape and sky. To me the S is missing.</td>', 'I am confused about the S in this photo. Where is it? Nice balloon, landscape and sky. To me the S is missing.', '2007-09-28 19:38:38.000000', NULL, 1),
(4123109, 589908, 43774, '<td valign="top">Oh I love this! What an amazing landscape.</td>', 'Oh I love this! What an amazing landscape.', '2007-09-28 19:38:56.000000', NULL, 1),
(4123111, 591652, 43774, '<td valign="top">What a gorgeous road, go back and shoot it in the autumn and it will be even more beautiful.</td>', 'What a gorgeous road, go back and shoot it in the autumn and it will be even more beautiful.', '2007-09-28 19:39:39.000000', NULL, 1),
(4123113, 589112, 43774, '<td valign="top">Beautiful photo, so clear</td>', 'Beautiful photo, so clear', '2007-09-28 19:39:55.000000', NULL, 1),
(4123114, 591821, 74741, '<td valign="top">I would like to see this in focus.</td>', 'I would like to see this in focus.', '2007-09-28 19:40:01.000000', NULL, 1),
(4123115, 589511, 43774, '<td valign="top">That is so cool, love the colours.</td>', 'That is so cool, love the colours.', '2007-09-28 19:40:08.000000', NULL, 1),
