(4133006, 590801, 59029, '<td valign="top">terrific capture. 9</td>', 'terrific capture. 9', '2007-10-02 12:22:11.000000', NULL, 1),
(4133094, 590596, 68035, '<td valign="top">Stunningly beautiful shot.  I love the black and white conversion and the strength and subtlty of the s curve.  May have preferred a slightly deeper dof so the ridge in the background was a tad sharper but definitely one of my personal ribbons  Bump to 9</td>', 'Stunningly beautiful shot.  I love the black and white conversion and the strength and subtlty of the s curve.  May have preferred a slightly deeper dof so the ridge in the background was a tad sharper but definitely one of my personal ribbons  Bump to 9', '2007-10-02 12:49:40.000000', NULL, 1),
(4133102, 591649, 68035, '<td valign="top">For me personally this is the best shot in the challenge.  It combines so many great elements, a fantastic s curve that is at once both subtle and obvious.  A great action shot with a crispness of focus to die for and a wonderful wonderful b&amp;w conversion<br/> <br/>10 from me and if this doesnt ribbon then I have no idea what would</td>', 'For me personally this is the best shot in the challenge.  It combines so many great elements, a fantastic s curve that is at once both subtle and obvious.  A great action shot with a crispness of focus to die for and a wonderful wonderful b&w conversion 10 from me and if this doesnt ribbon then I have no idea what would', '2007-10-02 12:51:33.000000', NULL, 1),
(4133110, 591723, 68035, '<td valign="top">How life can play cruel tricks on occasion.  I love this shot, it not only meets the challenge perfectly but it has been wonderfully executed.  It would have got a perfect 10 from me but the speed sign (which unfortunately hits right along a line of third that has been reversed when you flipped the picture is quite distracting to me.  I appreciate that you had to do the flip to get the s curve but I reckon that that may be what stops a fantastic shot being a ribbon winner in this challenge</td>', 'How life can play cruel tricks on occasion.  I love this shot, it not only meets the challenge perfectly but it has been wonderfully executed.  It would have got a perfect 10 from me but the speed sign (which unfortunately hits right along a line of third that has been reversed when you flipped the picture is quite distracting to me.  I appreciate that you had to do the flip to get the s curve but I reckon that that may be what stops a fantastic shot being a ribbon winner in this challenge', '2007-10-02 12:54:38.000000', NULL, 1),
(4133119, 591686, 68035, '<td valign="top">I dont know why but I just keep returning to this shot.  Love the pastel colours and the great repetitive shape of the jacks.  Maybe I would have preffered a fractionally sharper DOF but still a great 8</td>', 'I dont know why but I just keep returning to this shot.  Love the pastel colours and the great repetitive shape of the jacks.  Maybe I would have preffered a fractionally sharper DOF but still a great 8', '2007-10-02 12:56:26.000000', NULL, 1),
(4133124, 591679, 68035, '<td valign="top">One of my top three in the challenge love the misty background and how the elongated s curve is accentuated to a shorter one by the growth on the tree.  Great job and good luck</td>', 'One of my top three in the challenge love the misty background and how the elongated s curve is accentuated to a shorter one by the growth on the tree.  Great job and good luck', '2007-10-02 12:57:28.000000', NULL, 1),
