INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4135883, 591723, 31133, '<td valign="top">Whooohooo, you''re on a roll! Congratulations, Karen!</td>', 'Whooohooo, you''re on a roll! Congratulations, Karen!', '2007-10-03 01:49:56.000000', NULL, 0),
(4135884, 590664, 15511, '<td valign="top">I thought I recognized that bridge!</td>', 'I thought I recognized that bridge!', '2007-10-03 01:49:56.000000', NULL, 0),
(4135937, 591723, 16241, '<td valign="top">beautiful, congrats.</td>', 'beautiful, congrats.', '2007-10-03 02:11:15.000000', NULL, 0),
(4135941, 591649, 16241, '<td valign="top">very cool, well done.</td>', 'very cool, well done.', '2007-10-03 02:11:42.000000', NULL, 0),
(4135947, 591649, 68504, '<td valign="top">One of the really nice things is skateboarder''s white shirt parallel to upper rim.  (Agree about tilt;  also think a third or so cropped off the bottom, making a sort of question mark but still "S" ish would highlight subject better).</td>', 'One of the really nice things is skateboarder''s white shirt parallel to upper rim.  (Agree about tilt;  also think a third or so cropped off the bottom, making a sort of question mark but still "S" ish would highlight subject better).', '2007-10-03 02:13:28.000000', NULL, 0),
(4135967, 590596, 68504, '<td valign="top">Cunning abstract, and unlike other dune shots.  Gave you a 9.</td>', 'Cunning abstract, and unlike other dune shots.  Gave you a 9.', '2007-10-03 02:20:24.000000', NULL, 0),
(4135978, 591651, 68504, '<td valign="top">Fine twisty turny, sort of 3D S.  Excellent title.</td>', 'Fine twisty turny, sort of 3D S.  Excellent title.', '2007-10-03 02:26:23.000000', NULL, 0),
(4135983, 591317, 78303, '<td valign="top">People that commented seemed to be the most negative voters on this one.  There is something about the combination of the yello, the blue and the grey in this shot that still appeals to me.  Granted, the overall composition could have been more refined, or more "oomph" could have been drawn out of it.  But, as I was standing on the side of the road, trying not to fall in the ditch as cars whizzed by closely, I really wasn''t worried about all those other things.<br/> <br/>So, if you liked it, I am glad.  If you did not like it, so be it.  As you can tell, there is a bell curve of a response to the photo.</td>', 'People that commented seemed to be the most negative voters on this one.  There is something about the combination of the yello, the blue and the grey in this shot that still appeals to me.  Granted, the overall composition could have been more refined, or more "oomph" could have been drawn out of it.  But, as I was standing on the side of the road, trying not to fall in the ditch as cars whizzed by closely, I really wasn''t worried about all those other things. So, if you liked it, I am glad.  If you did not like it, so be it.  As you can tell, there is a bell curve of a response to the photo.', '2007-10-03 02:28:16.000000', NULL, 0),
(4135987, 591736, 67152, '<td valign="top">Congrats Del - This is awesome and so well deserved!</td>', 'Congrats Del - This is awesome and so well deserved!', '2007-10-03 02:29:17.000000', NULL, 0),
(4136003, 591209, 68504, '<td valign="top">Like the colour and texture of your sphynx(?) moth and the fleshy feet. Sgreat pose. (Has it a horn at the nether end?)</td>', 'Like the colour and texture of your sphynx(?) moth and the fleshy feet. Sgreat pose. (Has it a horn at the nether end?)', '2007-10-03 02:36:02.000000', NULL, 0),
(4136015, 591649, 64670, '<td valign="top">Jeff this is AWESOME and I particularly love that you had fun with your child - that''s combining your loves - GRIN!</td>', 'Jeff this is AWESOME and I particularly love that you had fun with your child - that''s combining your loves - GRIN!', '2007-10-03 02:41:15.000000', NULL, 0),
(4136021, 591636, 68504, '<td valign="top">Intriguing perspective.  Drama bottom left and upper right, but the real sweetness of the snaking water is where it almost disappears at the horizon.</td>', 'Intriguing perspective.  Drama bottom left and upper right, but the real sweetness of the snaking water is where it almost disappears at the horizon.', '2007-10-03 02:42:51.000000', NULL, 0),
(4136060, 589582, 68504, '<td valign="top">Nice macro showing discs on lower feet, and the little bristles, and the almost luminous green body - well, I''m a cat fan.</td>', 'Nice macro showing discs on lower feet, and the little bristles, and the almost luminous green body - well, I''m a cat fan.', '2007-10-03 03:01:56.000000', NULL, 0),
(4136083, 591723, 33352, '<td valign="top">Great work Karen, deserved a ribbon.</td>', 'Great work Karen, deserved a ribbon.', '2007-10-03 03:10:27.000000', NULL, 0),
