(4143359, 591365, 83758, '<td valign="top">Thanks for all who voted and especially those who commented. This was my first challenge entry, so I have embarked on a steep learning curve and enjoying every moment of it.<br/> <br/>I think the idea was good, but the execution was poor... I will do better next time.</td>', 'Thanks for all who voted and especially those who commented. This was my first challenge entry, so I have embarked on a steep learning curve and enjoying every moment of it. I think the idea was good, but the execution was poor... I will do better next time.', '2007-10-05 06:36:26.000000', NULL, 0),
(4144028, 591736, 27482, '<td valign="top">Congrats on the ribbon, like the play of light and shadows in this one.</td>', 'Congrats on the ribbon, like the play of light and shadows in this one.', '2007-10-05 11:52:57.000000', NULL, 0),
(4144030, 591723, 27482, '<td valign="top">Congrats on the ribbon!</td>', 'Congrats on the ribbon!', '2007-10-05 11:53:07.000000', NULL, 0),
